proxy_cache_path /var/cache/edge levels=1:2 keys_zone=edge:64m max_size=1g inactive=10m;

server {
  listen 443 ssl http2;
  ssl_certificate /etc/tls/edge.crt;
  ssl_certificate_key /etc/tls/edge.key;

  location /static/ {
    proxy_cache edge;
    proxy_cache_valid 200 5m;   # cache only success, short TTL
    proxy_cache_valid 404 30s;  # negative caching, even shorter
    proxy_cache_key "$scheme$host$uri"; # no Cookie -> shared entry
    proxy_pass http://app_upstream;
    proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    proxy_set_header X-Request-ID $request_id;
  }

  location /api/ {
    proxy_pass http://app_upstream;
    proxy_buffering off;          # stream uploads, do not spool
    proxy_read_timeout 5s;
    proxy_next_upstream error timeout http_502; # retry elsewhere
  }
}
